#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct metriche_op { uint64_t cmp, mov, acc; } metriche_op_t;

static void ordina_inserzione(int32_t *a, size_t n, metriche_op_t *m) {
    *m = (metriche_op_t){};
    for (size_t i = 1; i < n; ++i) {
        int32_t chiave = a[i]; ++m->acc;
        size_t j = i;
        while (j > 0) {
            ++m->cmp; ++m->acc;
            if (a[j - 1] > chiave) { a[j] = a[j - 1]; ++m->mov; m->acc += 2; --j; }
            else { break; }
        }
        if (j != i) { a[j] = chiave; ++m->acc; }
    }
}

static void ordina_shell(int32_t *a, size_t n, metriche_op_t *m) {
    *m = (metriche_op_t){};
    for (size_t gap = n / 2; gap > 0; gap /= 2) {
        for (size_t i = gap; i < n; ++i) {
            int32_t chiave = a[i]; ++m->acc;
            size_t j = i;
            while (j >= gap) {
                ++m->cmp; ++m->acc;
                if (a[j - gap] > chiave) { a[j] = a[j - gap]; ++m->mov; m->acc += 2; j -= gap; }
                else { break; }
            }
            if (j != i) { a[j] = chiave; ++m->acc; }
        }
    }
}

static void heap_scendi(int32_t *a, size_t n, size_t i, metriche_op_t *m) {
    while (true) {
        size_t sx = 2 * i + 1, dx = sx + 1, mag = i;
        if (sx < n) { ++m->cmp; m->acc += 2; if (a[sx] > a[mag]) { mag = sx; } }
        if (dx < n) { ++m->cmp; m->acc += 2; if (a[dx] > a[mag]) { mag = dx; } }
        if (mag == i) { break; }
        int32_t t = a[i]; a[i] = a[mag]; a[mag] = t;
        m->mov += 3; m->acc += 4;
        i = mag;
    }
}

static void ordina_heap(int32_t *a, size_t n, metriche_op_t *m) {
    *m = (metriche_op_t){};
    if (n <= 1) { return; }
    for (size_t i = n / 2; i > 0; --i) { heap_scendi(a, n, i - 1, m); }
    for (size_t fine = n - 1; fine > 0; --fine) {
        int32_t t = a[0]; a[0] = a[fine]; a[fine] = t;
        m->mov += 3; m->acc += 4;
        heap_scendi(a, fine, 0, m);
    }
}

static void esegui_confronto(const char *etichetta, const int32_t *base, size_t n) {
    int32_t a1[256] = {}, a2[256] = {}, a3[256] = {};
    if (n > 0) {
        memcpy(a1, base, n * sizeof(int32_t));
        memcpy(a2, base, n * sizeof(int32_t));
        memcpy(a3, base, n * sizeof(int32_t));
    }
    metriche_op_t m1 = {}, m2 = {}, m3 = {};
    ordina_inserzione(a1, n, &m1);
    ordina_shell(a2, n, &m2);
    ordina_heap(a3, n, &m3);
    bool ok = (n == 0) || (memcmp(a1, a2, n * sizeof(int32_t)) == 0 && memcmp(a1, a3, n * sizeof(int32_t)) == 0);
    printf("%s(%zu) ok=%d:\n", etichetta, n, ok ? 1 : 0);
    printf("  INS:   cmp=%" PRIu64 " mov=%" PRIu64 " acc=%" PRIu64 "\n", m1.cmp, m1.mov, m1.acc);
    printf("  SHELL: cmp=%" PRIu64 " mov=%" PRIu64 " acc=%" PRIu64 "\n", m2.cmp, m2.mov, m2.acc);
    printf("  HEAP:  cmp=%" PRIu64 " mov=%" PRIu64 " acc=%" PRIu64 "\n", m3.cmp, m3.mov, m3.acc);
}

int main(void) {
    char riga[512], cmd[16], modo[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t n = 0;
        int32_t dati[256] = {};
        if (strcmp(cmd, "BENCH") == 0 && sscanf(riga, "BENCH %15s %zu %c", modo, &n, &extra) == 2 && n >= 1 && n <= 256) {
            if (strcmp(modo, "ORD") == 0) {
                for (size_t i = 0; i < n; ++i) { dati[i] = (int32_t)i; }
                esegui_confronto("BENCH ORD", dati, n);
            } else if (strcmp(modo, "REV") == 0) {
                for (size_t i = 0; i < n; ++i) { dati[i] = (int32_t)(n - 1 - i); }
                esegui_confronto("BENCH REV", dati, n);
            } else if (strcmp(modo, "QUASI") == 0) {
                for (size_t i = 0; i < n; ++i) { dati[i] = (int32_t)i; }
                for (size_t i = 0; i + 1 < n; i += 8) { int32_t t = dati[i]; dati[i] = dati[i + 1]; dati[i + 1] = t; }
                esegui_confronto("BENCH QUASI", dati, n);
            } else { return EXIT_FAILURE; }
        } else if (strcmp(cmd, "CUSTOM") == 0) {
            int pos = 0;
            if (sscanf(riga, "CUSTOM %zu%n", &n, &pos) != 1 || n > 64) { return EXIT_FAILURE; }
            const char *p = riga + pos;
            for (size_t i = 0; i < n; ++i) {
                long v = 0; int av = 0;
                if (sscanf(p, "%ld%n", &v, &av) != 1 || v < INT32_MIN || v > INT32_MAX) { return EXIT_FAILURE; }
                dati[i] = (int32_t)v; p += av;
            }
            esegui_confronto("CUSTOM", dati, n);
        } else if (strcmp(cmd, "CLOCK_CHECK") == 0 && sscanf(riga, "CLOCK_CHECK %c", &extra) != 1) {
            clock_t t0 = clock();
            volatile uint64_t pozzo = 0;
            for (uint64_t k = 0; k < 10000; ++k) { pozzo += k; }
            clock_t t1 = clock();
            bool ok = (CLOCKS_PER_SEC > 0 && t0 != (clock_t)-1 && t1 != (clock_t)-1 &&
                       (double)(t1 - t0) / (double)CLOCKS_PER_SEC >= 0.0 && pozzo > 0);
            printf("CLOCK_CHECK: valido=%d\n", ok ? 1 : 0);
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}

