#ifndef CACHE_SIM_H
#define CACHE_SIM_H

#include <stddef.h>
#include <stdint.h>

constexpr size_t CACHE_LINEA = 64;
constexpr size_t CACHE_LINEE = 16;

typedef struct cache_sim {
    uint64_t tag[CACHE_LINEE];
    uint64_t ultimo[CACHE_LINEE];
    bool valida[CACHE_LINEE];
    uint64_t tick;
    uint64_t hits;
    uint64_t misses;
} cache_sim_t;

void cache_reset(cache_sim_t *c);
void cache_accedi(cache_sim_t *c, uint64_t offset_byte);

#endif

soluzione_file.cache_sim.c:
#include "cache_sim.h"
#include <string.h>

void cache_reset(cache_sim_t *c) {
    if (c != nullptr) { memset(c, 0, sizeof(*c)); }
}

void cache_accedi(cache_sim_t *c, uint64_t offset_byte) {
    uint64_t blocco = offset_byte / CACHE_LINEA;
    ++c->tick;
    size_t vittima = 0;
    uint64_t min_tick = UINT64_MAX;
    for (size_t i = 0; i < CACHE_LINEE; ++i) {
        if (c->valida[i] && c->tag[i] == blocco) {
            ++c->hits;
            c->ultimo[i] = c->tick;
            return;
        }
        if (!c->valida[i]) { vittima = i; min_tick = 0; }
        else if (c->ultimo[i] < min_tick) { min_tick = c->ultimo[i]; vittima = i; }
    }
    ++c->misses;
    c->valida[vittima] = true;
    c->tag[vittima] = blocco;
    c->ultimo[vittima] = c->tick;
}

