#include <inttypes.h>
#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cache_sim.h"

typedef struct particella_aos {
    double x, y, vx, vy;
    uint64_t id;
    uint32_t stato, gruppo;
    char etichetta[16];
} particella_aos_t;

static_assert(sizeof(particella_aos_t) == 64);

typedef struct particelle_soa {
    double *x, *y, *vx, *vy;
    uint32_t *stato;
    size_t n;
} particelle_soa_t;

static uint64_t allinea64(uint64_t v) { return (v + 63U) & ~(uint64_t)63; }

static bool run_step(size_t n, double dt) {
    particella_aos_t *aos = calloc(n, sizeof(*aos));
    particelle_soa_t soa = {.x = calloc(n, sizeof(double)), .y = calloc(n, sizeof(double)),
                            .vx = calloc(n, sizeof(double)), .vy = calloc(n, sizeof(double)), .n = n};
    if (!aos || !soa.x || !soa.y || !soa.vx || !soa.vy) {
        free(aos); free(soa.x); free(soa.y); free(soa.vx); free(soa.vy); return false;
    }
    for (size_t i = 0; i < n; ++i) {
        aos[i] = (particella_aos_t){.x = (double)i, .y = 2.0 * (double)i, .vx = 1.5, .vy = -0.5, .id = i, .stato = (uint32_t)(i % 4)};
        soa.x[i] = aos[i].x; soa.y[i] = aos[i].y; soa.vx[i] = aos[i].vx; soa.vy[i] = aos[i].vy;
    }
    cache_sim_t ca = {}, cs = {};
    double sa = 0.0, ss = 0.0;
    for (size_t i = 0; i < n; ++i) {
        uint64_t b = (uint64_t)i * sizeof(particella_aos_t);
        cache_accedi(&ca, b + offsetof(particella_aos_t, x));
        cache_accedi(&ca, b + offsetof(particella_aos_t, vx));
        cache_accedi(&ca, b + offsetof(particella_aos_t, y));
        cache_accedi(&ca, b + offsetof(particella_aos_t, vy));
        aos[i].x += aos[i].vx * dt; aos[i].y += aos[i].vy * dt;
        sa += aos[i].x + aos[i].y;
    }
    uint64_t stride = allinea64((uint64_t)n * sizeof(double));
    for (size_t i = 0; i < n; ++i) {
        cache_accedi(&cs, 0 * stride + (uint64_t)i * sizeof(double));
        cache_accedi(&cs, 2 * stride + (uint64_t)i * sizeof(double));
        cache_accedi(&cs, 1 * stride + (uint64_t)i * sizeof(double));
        cache_accedi(&cs, 3 * stride + (uint64_t)i * sizeof(double));
        soa.x[i] += soa.vx[i] * dt; soa.y[i] += soa.vy[i] * dt;
        ss += soa.x[i] + soa.y[i];
    }
    printf("STEP(%zu) ok=%d:\n", n, (fabs(sa - ss) < 1e-9) ? 1 : 0);
    printf("  AoS: hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", ca.hits, ca.misses, ca.misses * CACHE_LINEA);
    printf("  SoA: hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", cs.hits, cs.misses, cs.misses * CACHE_LINEA);
    free(aos); free(soa.x); free(soa.y); free(soa.vx); free(soa.vy);
    return true;
}

static void run_filtra(size_t n, uint32_t req) {
    cache_sim_t ca = {}, cs = {};
    size_t c1 = 0, c2 = 0;
    for (size_t i = 0; i < n; ++i) {
        cache_accedi(&ca, (uint64_t)i * sizeof(particella_aos_t) + offsetof(particella_aos_t, stato));
        if ((uint32_t)(i % 4) == req) { ++c1; }
    }
    for (size_t i = 0; i < n; ++i) {
        cache_accedi(&cs, (uint64_t)i * sizeof(uint32_t));
        if ((uint32_t)(i % 4) == req) { ++c2; }
    }
    printf("FILTRA(%zu, %" PRIu32 ") cnt=%zu ok=%d:\n", n, req, c1, (c1 == c2) ? 1 : 0);
    printf("  AoS: hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", ca.hits, ca.misses, ca.misses * CACHE_LINEA);
    printf("  SoA: hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", cs.hits, cs.misses, cs.misses * CACHE_LINEA);
}

static void run_matrice(size_t r, size_t c) {
    cache_sim_t cr = {}, cc = {};
    uint64_t s1 = 0, s2 = 0;
    for (size_t i = 0; i < r; ++i) {
        for (size_t j = 0; j < c; ++j) {
            cache_accedi(&cr, ((uint64_t)i * c + j) * sizeof(double)); s1 += i + j;
        }
    }
    for (size_t j = 0; j < c; ++j) {
        for (size_t i = 0; i < r; ++i) {
            cache_accedi(&cc, ((uint64_t)i * c + j) * sizeof(double)); s2 += i + j;
        }
    }
    printf("MATRICE(%zux%zu) ok=%d:\n", r, c, (s1 == s2) ? 1 : 0);
    printf("  RIGHE:   hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", cr.hits, cr.misses, cr.misses * CACHE_LINEA);
    printf("  COLONNE: hits=%" PRIu64 " misses=%" PRIu64 " byte=%" PRIu64 "\n", cc.hits, cc.misses, cc.misses * CACHE_LINEA);
}

int main(void) {
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t n = 0, r = 0, c = 0; double dt = 0.0; unsigned int st = 0;
        if (strcmp(cmd, "STEP") == 0 && sscanf(riga, "STEP %zu %lf %c", &n, &dt, &extra) == 2 && n >= 1 && n <= 512) {
            if (!run_step(n, dt)) { return EXIT_FAILURE; }
        } else if (strcmp(cmd, "FILTRA") == 0 && sscanf(riga, "FILTRA %zu %u %c", &n, &st, &extra) == 2 && n >= 1 && n <= 512) {
            run_filtra(n, (uint32_t)st);
        } else if (strcmp(cmd, "MATRICE") == 0 && sscanf(riga, "MATRICE %zu %zu %c", &r, &c, &extra) == 2 && r >= 1 && r <= 64 && c >= 1 && c <= 64) {
            run_matrice(r, c);
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}

