#include <inttypes.h>
#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static_assert(sizeof(float) == sizeof(uint32_t));

static bool somma_sicura_i32(int32_t a, int32_t b, int32_t *out) {
    return !ckd_add(out, a, b);
}

static bool prod_sicuro_i64(int64_t a, int64_t b, int64_t *out) {
    return !ckd_mul(out, a, b);
}

static bool shift_sicuro_u32(uint32_t x, int k, bool sinistra, uint32_t *out) {
    if (k < 0 || k >= 32 || out == nullptr) { return false; }
    *out = sinistra ? (x << k) : (x >> k);
    return true;
}

static uint32_t float_a_bit(float f) {
    uint32_t u = 0;
    memcpy(&u, &f, sizeof(u));
    return u;
}

static float bit_a_float(uint32_t u) {
    float f = 0.0f;
    memcpy(&f, &u, sizeof(f));
    return f;
}

static void combina_restrict(size_t n, double *restrict dst, const double *restrict a,
                             const double *restrict b, double alpha) {
    for (size_t i = 0; i < n; ++i) { dst[i] = alpha * a[i] + b[i]; }
}

static bool sovrapposti(const void *p1, const void *p2, size_t n_byte) {
    if (n_byte == 0) { return false; }
    uintptr_t a1 = (uintptr_t)p1, a2 = (uintptr_t)p2;
    return (a1 < a2 + n_byte) && (a2 < a1 + n_byte);
}

static bool combina_sicura(size_t n, double *dst, const double *a, const double *b,
                           double alpha, bool *usato_restrict) {
    if (n == 0) { *usato_restrict = true; return true; }
    size_t nb = n * sizeof(double);
    if (!sovrapposti(dst, a, nb) && !sovrapposti(dst, b, nb)) {
        *usato_restrict = true;
        combina_restrict(n, dst, a, b, alpha);
        return true;
    }
    *usato_restrict = false;
    double *tmp = malloc(nb);
    if (tmp == nullptr) { return false; }
    for (size_t i = 0; i < n; ++i) { tmp[i] = alpha * a[i] + b[i]; }
    memcpy(dst, tmp, nb);
    free(tmp);
    return true;
}

int main(void) {
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long a64 = 0, b64 = 0;
        unsigned int u = 0; int k = 0; double d = 0.0;
        if (strcmp(cmd, "ADD32") == 0 && sscanf(riga, "ADD32 %lld %lld %c", &a64, &b64, &extra) == 2 &&
            a64 >= INT32_MIN && a64 <= INT32_MAX && b64 >= INT32_MIN && b64 <= INT32_MAX) {
            int32_t r = 0;
            if (somma_sicura_i32((int32_t)a64, (int32_t)b64, &r)) { printf("ADD32: OK %" PRId32 "\n", r); }
            else { printf("ADD32: OVERFLOW\n"); }
        } else if (strcmp(cmd, "MUL64") == 0 && sscanf(riga, "MUL64 %lld %lld %c", &a64, &b64, &extra) == 2) {
            int64_t r = 0;
            if (prod_sicuro_i64((int64_t)a64, (int64_t)b64, &r)) { printf("MUL64: OK %" PRId64 "\n", r); }
            else { printf("MUL64: OVERFLOW\n"); }
        } else if ((strcmp(cmd, "SHL32") == 0 || strcmp(cmd, "SHR32") == 0) &&
                   sscanf(riga, "%*15s %u %d %c", &u, &k, &extra) == 2) {
            uint32_t r = 0;
            bool sx = (strcmp(cmd, "SHL32") == 0);
            if (shift_sicuro_u32((uint32_t)u, k, sx, &r)) { printf("%s: OK 0x%08" PRIx32 "\n", cmd, r); }
            else { printf("%s: ERR_SHIFT\n", cmd); }
        } else if (strcmp(cmd, "FBITS") == 0 && sscanf(riga, "FBITS %lf %c", &d, &extra) == 1) {
            uint32_t bits = float_a_bit((float)d);
            printf("FBITS: hex=0x%08" PRIx32 " rt=%.2f\n", bits, (double)bit_a_float(bits));
        } else if ((strcmp(cmd, "VEC_DISJ") == 0 || strcmp(cmd, "VEC_OVERLAP") == 0) &&
                   sscanf(riga, "%*15s %lf %c", &d, &extra) == 1) {
            double va[4] = {1.0, 2.0, 3.0, 4.0}, vb[4] = {10.0, 20.0, 30.0, 40.0}, vd[4] = {};
            double *dst = (strcmp(cmd, "VEC_DISJ") == 0) ? vd : va;
            bool ur = false;
            if (!combina_sicura(4, dst, va, vb, d, &ur)) { return EXIT_FAILURE; }
            printf("%s: restrict=%d [%.2f %.2f %.2f %.2f]\n", cmd, ur ? 1 : 0, dst[0], dst[1], dst[2], dst[3]);
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}

