#ifndef TEST_FW_H
#define TEST_FW_H

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

typedef struct test_ctx {
    size_t eseguiti, superati, falliti, ass_ok, ass_ko;
    bool corrente_ko;
} test_ctx_t;

typedef void (*test_fn)(test_ctx_t *ctx);
typedef struct caso_test { const char *nome; test_fn fn; } caso_test_t;

#define T_VERO(ctx, cond) do { \
    if (cond) { ++(ctx)->ass_ok; } \
    else { ++(ctx)->ass_ko; (ctx)->corrente_ko = true; printf("  [ASS_FAIL] %s: %s\n", __func__, #cond); } \
} while (0)

#define T_EQ_I32(ctx, att, ott, expr_txt) do { \
    int32_t _a = (att), _o = (ott); \
    if (_a == _o) { ++(ctx)->ass_ok; } \
    else { ++(ctx)->ass_ko; (ctx)->corrente_ko = true; \
           printf("  [ASS_FAIL] %s: %s (att=%" PRId32 " ott=%" PRId32 ")\n", __func__, (expr_txt), _a, _o); } \
} while (0)

#define T_EQ_ZU(ctx, att, ott) do { \
    size_t _a = (att), _o = (ott); \
    if (_a == _o) { ++(ctx)->ass_ok; } \
    else { ++(ctx)->ass_ko; (ctx)->corrente_ko = true; \
           printf("  [ASS_FAIL] %s: %s == %s (att=%zu ott=%zu)\n", __func__, #att, #ott, _a, _o); } \
} while (0)

static inline void test_esegui(test_ctx_t *ctx, const caso_test_t *c) {
    ctx->corrente_ko = false;
    c->fn(ctx);
    ++ctx->eseguiti;
    if (ctx->corrente_ko) { ++ctx->falliti; printf("[FAIL] %s\n", c->nome); }
    else { ++ctx->superati; printf("[PASS] %s\n", c->nome); }
}

#endif

