#include "ring_buf.h"
#include <stdlib.h>

struct ring { int32_t *dati; size_t cap, testa, coda, len; };

ring_t *ring_crea(size_t cap) {
    if (cap == 0) { return nullptr; }
    ring_t *r = calloc(1, sizeof(*r));
    if (r == nullptr) { return nullptr; }
    r->dati = calloc(cap, sizeof(*r->dati));
    if (r->dati == nullptr) { free(r); return nullptr; }
    r->cap = cap;
    return r;
}

void ring_distruggi(ring_t *r) { if (r != nullptr) { free(r->dati); free(r); } }

bool ring_push(ring_t *r, int32_t val) {
    if (r == nullptr || r->len == r->cap) { return false; }
    r->dati[r->coda] = val;
    r->coda = (r->coda + 1) % r->cap;
    ++r->len;
    return true;
}

bool ring_pop(ring_t *r, int32_t *out) {
    if (r == nullptr || r->len == 0) { return false; }
    if (out != nullptr) { *out = r->dati[r->testa]; }
    r->testa = (r->testa + 1) % r->cap;
    --r->len;
    return true;
}

size_t ring_len(const ring_t *r) { return (r != nullptr) ? r->len : 0; }
size_t ring_cap(const ring_t *r) { return (r != nullptr) ? r->cap : 0; }
bool ring_vuoto(const ring_t *r) { return ring_len(r) == 0; }
bool ring_pieno(const ring_t *r) { return (r != nullptr) && (r->len == r->cap); }

