#include "mappa_ord.h"
#include <stdckdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct coppia { int32_t k, v; } coppia_t;
struct mappa_ord { coppia_t *voci; size_t len, cap; };

static size_t lower_bound(const mappa_ord_t *m, int32_t k) {
    size_t sx = 0, dx = m->len;
    while (sx < dx) {
        size_t mid = sx + (dx - sx) / 2;
        if (m->voci[mid].k < k) { sx = mid + 1; } else { dx = mid; }
    }
    return sx;
}

mappa_ord_t *mappa_crea(void) { return calloc(1, sizeof(mappa_ord_t)); }
void mappa_distruggi(mappa_ord_t *m) { if (m != nullptr) { free(m->voci); free(m); } }

bool mappa_put(mappa_ord_t *m, int32_t k, int32_t v, bool *agg) {
    if (m == nullptr) { return false; }
    size_t pos = lower_bound(m, k);
    if (pos < m->len && m->voci[pos].k == k) {
        m->voci[pos].v = v;
        if (agg != nullptr) { *agg = true; }
        return true;
    }
    if (m->len == m->cap) {
        size_t ncap = (m->cap == 0) ? 4 : 0;
        if (ncap == 0 && ckd_mul(&ncap, m->cap, 2)) { return false; }
        size_t nb = 0;
        if (ckd_mul(&nb, ncap, sizeof(*m->voci))) { return false; }
        coppia_t *nv = realloc(m->voci, nb);
        if (nv == nullptr) { return false; }
        m->voci = nv; m->cap = ncap;
    }
    if (pos < m->len) {
        memmove(&m->voci[pos + 1], &m->voci[pos], (m->len - pos) * sizeof(*m->voci));
    }
    m->voci[pos] = (coppia_t){.k = k, .v = v};
    ++m->len;
    if (agg != nullptr) { *agg = false; }
    return true;
}

bool mappa_get(const mappa_ord_t *m, int32_t k, int32_t *out) {
    if (m == nullptr) { return false; }
    size_t pos = lower_bound(m, k);
    if (pos >= m->len || m->voci[pos].k != k) { return false; }
    if (out != nullptr) { *out = m->voci[pos].v; }
    return true;
}

bool mappa_del(mappa_ord_t *m, int32_t k) {
    if (m == nullptr) { return false; }
    size_t pos = lower_bound(m, k);
    if (pos >= m->len || m->voci[pos].k != k) { return false; }
    if (pos + 1 < m->len) {
        memmove(&m->voci[pos], &m->voci[pos + 1], (m->len - pos - 1) * sizeof(*m->voci));
    }
    --m->len;
    return true;
}

size_t mappa_len(const mappa_ord_t *m) { return (m != nullptr) ? m->len : 0; }

bool mappa_invariante_ok(const mappa_ord_t *m) {
    if (m == nullptr || m->len > m->cap) { return false; }
    for (size_t i = 1; i < m->len; ++i) {
        if (m->voci[i - 1].k >= m->voci[i].k) { return false; }
    }
    return true;
}

