#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mappa_ord.h"

static_assert(RAND_MAX >= 32767);

static bool esegui_fuzz(unsigned int seme, size_t passi, size_t max_k) {
    mappa_ord_t *m = mappa_crea();
    if (m == nullptr) { return false; }
    bool pres[64] = {};
    int32_t val_or[64] = {};
    size_t len_or = 0, ok_passi = 0, errori = 0;
    bool inv_tutto = true;
    srand(seme);
    for (size_t p = 0; p < passi; ++p) {
        int op = rand() % 3;
        size_t k = (size_t)(rand() % (int)max_k);
        int32_t v = (int32_t)(rand() % 2001) - 1000;
        bool passo_ok = true;
        if (op == 0) {
            bool agg = false;
            if (!mappa_put(m, (int32_t)k, v, &agg) || agg != pres[k]) { passo_ok = false; }
            if (!pres[k]) { pres[k] = true; ++len_or; }
            val_or[k] = v;
        } else if (op == 1) {
            bool rim = mappa_del(m, (int32_t)k);
            if (rim != pres[k]) { passo_ok = false; }
            if (pres[k]) { pres[k] = false; --len_or; }
        } else {
            int32_t letto = 0;
            bool trov = mappa_get(m, (int32_t)k, &letto);
            if (trov != pres[k] || (trov && letto != val_or[k])) { passo_ok = false; }
        }
        bool inv = mappa_invariante_ok(m);
        if (!inv) { inv_tutto = false; }
        if (passo_ok && inv && mappa_len(m) == len_or) { ++ok_passi; } else { ++errori; }
    }
    for (size_t k = 0; k < max_k; ++k) {
        int32_t letto = 0;
        bool trov = mappa_get(m, (int32_t)k, &letto);
        if (trov != pres[k] || (trov && letto != val_or[k])) { ++errori; }
    }
    printf("FUZZ(seme=%u, passi=%zu, k=%zu): ok=%zu/%zu errori=%zu inv_ok=%d\n",
           seme, passi, max_k, ok_passi, passi, errori, inv_tutto ? 1 : 0);
    mappa_distruggi(m);
    return true;
}

int main(void) {
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned int seme = 0; size_t passi = 0, max_k = 0;
        if (strcmp(cmd, "FUZZ") == 0 &&
            sscanf(riga, "FUZZ %u %zu %zu %c", &seme, &passi, &max_k, &extra) == 3 &&
            passi >= 1 && passi <= 5000 && max_k >= 1 && max_k <= 64) {
            if (!esegui_fuzz(seme, passi, max_k)) { return EXIT_FAILURE; }
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}
